public static String classAverages(int[][] grades) {
    String s = "";
    for (int i = 0; i < grades.length; i++) {
        int sum = 0;
        for (int j = 0; j < grades[i].length; j++) {
            sum = sum + grades[i][j];
        }
        s = s + (double) sum / grades[i].length + " ";
    }
    return s;
}

public static String failCounts(int[][] grades) {
    String s = "";
    for (int i = 0; i < grades.length; i++) {
        int count = 0;
        for (int j = 0; j < grades[i].length; j++) {
            if (grades[i][j] < 55) {
                count++;
            }
        }
        s = s + count + " ";
    }
    return s;
}

public static String highestGrades(int[][] grades) {
    String s = "";
    for (int i = 0; i < grades.length; i++) {
        int max = grades[i][0];
        for (int j = 1; j < grades[i].length; j++) {
            if (grades[i][j] > max) {
                max = grades[i][j];
            }
        }
        s = s + max + " ";
    }
    return s;
}

